//! 🧪️ Production ledger readers retain the actual authored row and native original caller through every close.
use super::*;
use semio_framework_plugin_tool_run::original_operations::OriginalToolLedgerRead;
use semio_framework_tool_machine::{OriginalToolLedgerSource,TypingLedger,TypingState,TypingInput,TypingFold};
fn denied(d:RetirementDemand)->Vec<RetainedCloneGrant>{let mut out=vec![RetainedCloneGrant{maximum_items:0,..TURN}];if d.copy_bytes>0{out.push(RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes-1,..TURN})}if d.capacity_bytes>0{out.push(RetainedCloneGrant{maximum_capacity_bytes:d.capacity_bytes-1,..TURN})}if d.release_bytes>0{out.push(RetainedCloneGrant{maximum_release_bytes:d.release_bytes-1,..TURN})}if d.depth>0{out.push(RetainedCloneGrant{maximum_depth:d.depth-1,..TURN})}out}
#[test]fn original_production_ledger_reader_keeps_same_authored_state_and_caller_until_return(){
 let law:serde_json::Value=serde_json::from_str(include_str!("../../../../../../../../🧰️framework/🛍️products/💻️os/🔨️modules/🔌️plugin/🛠️tool-machine/🔁️follow/🧪️tests/🔣️.json")).unwrap();
 for cut in std::iter::once(None).chain(law["cancelCuts"].as_array().unwrap().iter().map(|cut|Some(cut.as_u64().unwrap()))){let mut ledger=TypingLedger::<u64>::default();ledger.send("reader","native#typing",&store::ActorId("reader".into()),TypingInput::Edit{buffer:"text".into(),leaves:(0..8197).collect()},|_,next|TypingFold::Net(next.to_vec()),store::HybridLogicalTimestamp{actor:0,physical_ms:10,logical:0}).unwrap();let pointer=ledger.open("reader").unwrap().entries.as_ptr();let revision=ledger.source_revision();let mut caller=caller();let mut decoder=OriginalJobDecodeOwner::empty();let mut reader=OriginalToolLedgerRead::<TypingState<u64>>::default();let mut admitted=false;let mut ready=false;
 for index in 0..65536{if cut==Some(index){break}let d=if admitted{reader.demands(&ledger,4096).unwrap()}else{OriginalToolLedgerRead::<TypingState<u64>>::admission_demands()};for grant in denied(d){turn(&mut caller,&mut decoder,grant,|cx|{if admitted{assert!(!reader.advance(&mut ledger,cx)?);}else{let(window,key)=ledger.original_next(None).unwrap();assert!(!reader.admit(&ledger,window,key,cx)?);}Ok(())});assert_eq!(caller.receipt(),Default::default());assert_eq!(reader.ready(),false);}
 if admitted{ready=turn(&mut caller,&mut decoder,TURN,|cx|reader.advance(&mut ledger,cx));}else{admitted=turn(&mut caller,&mut decoder,TURN,|cx|{let(window,key)=ledger.original_next(None).unwrap();reader.admit(&ledger,window,key,cx)});}if ready{break}assert!(index<65535);}
 if cut.is_none(){assert!(ready);assert_eq!(reader.borrow(&ledger).unwrap().get().entries.as_ptr(),pointer);assert!(ledger.commit("reader",semio_framework_tool_machine::TypingCommit::Enter,store::HybridLogicalTimestamp{actor:0,physical_ms:20,logical:0}).is_err());}
 if admitted{let mut foreign=OriginalJobDecodeOwner::empty();let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.turn_with_decoder(TURN,&mut foreign,|cx|reader.advance(&mut ledger,cx)));assert!(result.is_err());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert!(foreign.terminal_is_empty());}
 caller.cancel().cancel_now();for index in 0..65536{if reader.terminal_is_empty(){break}let d=reader.close_demands(&ledger,4096).unwrap();for grant in denied(d){turn(&mut caller,&mut decoder,grant,|cx|cx.with_original_retirement(|cx|{assert!(!reader.close_step(&mut ledger,cx)?);Ok(())}));assert_eq!(caller.receipt(),Default::default());}turn(&mut caller,&mut decoder,TURN,|cx|cx.with_original_retirement(|cx|reader.close_step(&mut ledger,cx)));assert!(index<65535);}assert!(reader.terminal_is_empty());assert_eq!(ledger.source_revision(),revision);assert_eq!(ledger.open("reader").unwrap().entries.as_ptr(),pointer);assert!(!ledger.retained_read_pending("reader"));while !decoder.terminal_is_empty(){caller.turn(TURN,|cx|cx.with_original_retirement(|cx|{let d=decoder.retirement_demands(4096)?;close_original_retained_step(cx,d,|g|decoder.close_step(g))?;Ok(())})).unwrap();}caller.retire(TURN);
 }
}
#[test]
fn original_production_ledger_walk_visits_original_rows_without_a_collected_key_list(){
 use semio_framework_plugin_tool_run::original_operations::OriginalToolLedgerWalk;
 let law:serde_json::Value=serde_json::from_str(include_str!("../../../../../../../../🧰️framework/🛍️products/💻️os/🔨️modules/🔌️plugin/🛠️tool-machine/🔁️follow/🧪️tests/🔣️.json")).unwrap();
 for cut in std::iter::once(None).chain(law["cancelCuts"].as_array().unwrap().iter().map(|cut|Some(cut.as_u64().unwrap()))){let mut ledger=TypingLedger::<u64>::default();for(window,value)in[("a",2u64),("b",7)]{ledger.send(window,"native#typing",&store::ActorId("walk".into()),TypingInput::Edit{buffer:"text".into(),leaves:vec![value]},|_,next|TypingFold::Net(next.to_vec()),store::HybridLogicalTimestamp{actor:0,physical_ms:10,logical:0}).unwrap();}let pointers=[ledger.open("a").unwrap().entries.as_ptr(),ledger.open("b").unwrap().entries.as_ptr()];let mut caller=caller();let mut decoder=OriginalJobDecodeOwner::empty();let mut walk=OriginalToolLedgerWalk::<TypingState<u64>>::default();let mut visited=0;
 for index in 0..65536{if cut==Some(index){break}if walk.done(){break}if walk.ready(){assert_eq!(walk.borrow(&ledger).unwrap().get().entries.as_ptr(),pointers[visited]);let d=OriginalToolLedgerWalk::<TypingState<u64>>::return_demands();for g in denied(d){assert!(!turn(&mut caller,&mut decoder,g,|cx|walk.finish_row(cx)));assert_eq!(caller.receipt(),Default::default());}assert!(turn(&mut caller,&mut decoder,TURN,|cx|walk.finish_row(cx)));visited+=1;continue}let d=walk.demands(&ledger,4096).unwrap();for g in denied(d){assert!(!turn(&mut caller,&mut decoder,g,|cx|walk.advance(&mut ledger,cx)));assert_eq!(caller.receipt(),Default::default());}turn(&mut caller,&mut decoder,TURN,|cx|walk.advance(&mut ledger,cx));assert!(index<65535);}
 if cut.is_none(){assert!(walk.done());assert_eq!(visited,2)}caller.cancel().cancel_now();for index in 0..65536{if walk.terminal_is_empty(){break}let d=walk.close_demands(&ledger,4096).unwrap();for g in denied(d){assert!(!turn(&mut caller,&mut decoder,g,|cx|cx.with_original_retirement(|cx|walk.close_step(&mut ledger,cx))));assert_eq!(caller.receipt(),Default::default());}turn(&mut caller,&mut decoder,TURN,|cx|cx.with_original_retirement(|cx|walk.close_step(&mut ledger,cx)));assert!(index<65535);}assert_eq!(ledger.open("a").unwrap().entries.as_ptr(),pointers[0]);assert_eq!(ledger.open("b").unwrap().entries.as_ptr(),pointers[1]);while !decoder.terminal_is_empty(){caller.turn(TURN,|cx|cx.with_original_retirement(|cx|{let d=decoder.retirement_demands(4096)?;close_original_retained_step(cx,d,|g|decoder.close_step(g))?;Ok(())})).unwrap();}caller.retire(TURN);
 }
}
